import { useEffect, useRef } from 'react'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'

import markerIcon2x from 'leaflet/dist/images/marker-icon-2x.png'
import markerIcon from 'leaflet/dist/images/marker-icon.png'
import markerShadow from 'leaflet/dist/images/marker-shadow.png'

// import './Mapa.css'

delete L.Icon.Default.prototype._getIconUrl

L.Icon.Default.mergeOptions({
  iconRetinaUrl: markerIcon2x,
  iconUrl: markerIcon,
  shadowUrl: markerShadow,
})

const GOOGLE_MAPS_API_KEY = process.env.REACT_APP_GOOGLE_MAPS_API_KEY

function loadScript(src) {
  return new Promise((resolve, reject) => {
    const existingScript = document.querySelector(`script[src="${src}"]`)

    if (existingScript) {
      if (existingScript.dataset.loaded === 'true') {
        resolve()
        return
      }

      existingScript.addEventListener('load', () => resolve(), { once: true })
      existingScript.addEventListener('error', () => reject(new Error(`Falha ao carregar script: ${src}`)), { once: true })
      return
    }

    const script = document.createElement('script')
    script.src = src
    script.async = true
    script.defer = true
    script.onload = () => {
      script.dataset.loaded = 'true'
      resolve()
    }
    script.onerror = () => reject(new Error(`Falha ao carregar script: ${src}`))
    document.head.appendChild(script)
  })
}

function Mapa() {
  const mapRef = useRef(null)
  const mapInstanceRef = useRef(null)

  useEffect(() => {
    let cancelled = false

    async function initializeMap() {
      if (!mapRef.current || mapInstanceRef.current) return

      const map = L.map(mapRef.current).setView([-23.55, -46.63], 13)
      mapInstanceRef.current = map

      try {
        if (!GOOGLE_MAPS_API_KEY) {
          throw new Error('Defina REACT_APP_GOOGLE_MAPS_API_KEY no arquivo .env')
        }

        await loadScript(`https://maps.googleapis.com/maps/api/js?key=${GOOGLE_MAPS_API_KEY}&v=weekly`)
        await loadScript('https://unpkg.com/leaflet.gridlayer.googlemutant@0.14.0/Leaflet.GoogleMutant.js')

        if (!L.gridLayer || typeof L.gridLayer.googleMutant !== 'function') {
          throw new Error('Plugin GoogleMutant nao foi carregado corretamente')
        }

        L.gridLayer.googleMutant({
          type: 'roadmap',
        }).addTo(map)
      } catch (error) {
        console.error('Falha ao inicializar Google Maps no Leaflet. Aplicando fallback OSM.', error)
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
          attribution: '&copy; OpenStreetMap contributors',
        }).addTo(map)
      }

      if (!cancelled) {
        buscarPontosDeInteresse(map)
      }
    }

    initializeMap()

    return () => {
      cancelled = true

      if (mapInstanceRef.current) {
        mapInstanceRef.current.remove()
        mapInstanceRef.current = null
      }

      // Evita erro de "Map container is already initialized" no StrictMode do React.
      if (mapRef.current && mapRef.current._leaflet_id) {
        delete mapRef.current._leaflet_id
      }
    }
  }, [])

  return <div ref={mapRef} style={{ height: '100vh', width: '100%', zIndex: 0 }} />
}

function buscarPontosDeInteresse(map) {
  fetch('http://localhost:8080/api/local/all')
    .then(response => response.json())
    .then(data => {
      data.forEach(restaurante => {
        L.marker([restaurante.latitude, restaurante.longitude])
          .bindPopup(`<b>${restaurante.nome}</b><br>${restaurante.endereco.bairro}`)
          .addTo(map)
      })
    })
    .catch(error => console.error('Error fetching restaurant data:', error))
}


export default Mapa
